// Validate and extract question + documentId
const body = $input.first().json.body;

if (!body.question || !body.documentId) {
  throw new Error('Missing required fields: question and documentId');
}

return [{
  json: {
    question: body.question.trim(),
    documentId: body.documentId
  }
}];

// Prepare Pinecone query payload
const embeddingResponse = $input.first().json;
const questionData = $('Validate Input').first().json;

const vector = embeddingResponse.data?.[0]?.embedding;
if (!vector || !Array.isArray(vector)) {
  throw new Error('No embedding returned: ' + JSON.stringify(embeddingResponse));
}

return [{
  json: {
    question: questionData.question,
    documentId: questionData.documentId,
    queryVector: vector,
    topK: 5,
    filter: {
      documentId: { '$eq': questionData.documentId }
    }
  }
}];

// Assemble context from Pinecone results and build LLM prompt
const pineconeResult = $input.first().json;
const question = $('Validate Input').first().json.question;
const documentId = $('Validate Input').first().json.documentId;

const matches = pineconeResult.matches || [];

if (matches.length === 0) {
  throw new Error('No relevant content found in the document for this question.');
}

// Build context from top matches
const contextParts = matches.map((match, idx) => {
  const meta = match.metadata || {};
  return `[Source ${idx + 1} - Page ${meta.pageEstimate || '?'}, Score: ${(match.score || 0).toFixed(2)}]\n${meta.content || ''}`;
});

const context = contextParts.join('\n\n---\n\n');

// Extract sources for attribution
const sources = matches.map(match => ({
  filename: match.metadata?.filename || 'Unknown',
  page: match.metadata?.pageEstimate || null,
  score: match.score || 0,
  content: (match.metadata?.content || '').substring(0, 200)
}));

const systemPrompt = `You are a helpful document assistant. Answer the user's question based ONLY on the provided context.
If the context does not contain enough information to answer the question, say so clearly.
Always be concise and accurate. Do not make up information not present in the context.`;

const userMessage = `Context from document:\n\n${context}\n\n---\n\nQuestion: ${question}\n\nAnswer based on the context above:`;

return [{
  json: {
    question,
    documentId,
    sources,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userMessage }
    ]
  }
}];

// Parse LLM response and build final answer with sources
const llmResponse = $input.first().json;
const contextData = $('Assemble Context').first().json;

const answer = llmResponse.choices?.[0]?.message?.content;
if (!answer) {
  throw new Error('No answer returned from LLM: ' + JSON.stringify(llmResponse));
}

return [{
  json: {
    answer: answer.trim(),
    sources: contextData.sources,
    question: contextData.question,
    documentId: contextData.documentId
  }
}];
